 page.querySelectorAll("[data-rx-move]").forEach(b=>b.onclick=()=>{const i=+b.dataset.rxMove,j=i+ +b.dataset.dir;[r.exercises[i],r.exercises[j]]=[r.exercises[j],r.exercises[i]];save()});
