 // search
 page.querySelector("#openSearch").onclick=()=>{foodSearch.open=true;page.querySelector("#searchBox").classList.remove("hidden");page.querySelector("#searchQuery").focus()};
 const go=()=>{const q=page.querySelector("#searchQuery").value.trim();if(q)runFoodSearch(q)};
 page.querySelector("#runSearch").onclick=go;page.querySelector("#searchQuery").onkeydown=e=>{if(e.key==="Enter"){e.preventDefault();go()}};
 page.querySelectorAll("[data-result]").forEach(b=>b.onclick=()=>pickFood(foodSearch.results[+b.dataset.result]));
 page.querySelector("#closeSearch")?.addEventListener("click",()=>{foodSearch={query:"",results:null,loading:false,error:"",picked:null};drawFood()});
 const p=foodSearch.picked;
 if(p){const upd=()=>{p.amount=+page.querySelector("#pickAmount").value||0;p.unit=page.querySelector("#pickUnit").value;page.querySelector("#pickTotals").textContent=macroText(pickedNutrition(p))};page.querySelector("#pickAmount").oninput=upd;page.querySelector("#pickUnit").onchange=upd;
  page.querySelector("#pickBack").onclick=()=>{foodSearch.picked=null;if(!foodSearch.results)foodSearch.open=false;drawFood()};
  page.querySelector("#pickUse").onclick=()=>{upd();const n=pickedNutrition(p);if(!(pickedGrams(p)>0))return alert("Enter an amount.");const name=`${p.name} (${pickedLabel(p)})`;foodSearch={query:"",results:null,loading:false,error:"",picked:null};drawFood();fillFoodForm($("#page-food"),{name,...n});$("#saveFood").scrollIntoView({block:"center",behavior:"smooth"})}}
