// ---- Barcode scanner (camera via ZXing, with typed-number and photo fallbacks)
let scanControls=null;
function stopScanner(){try{scanControls?.stop()}catch{}scanControls=null;const v=$("#scanVideo");if(v?.srcObject){v.srcObject.getTracks?.().forEach(t=>t.stop());v.srcObject=null}}
async function openScanner(){const dlg=$("#scanDialog");$("#scanStatus").textContent="Starting camera…";$("#scanCode").value="";dlg.showModal();
 try{const V=await loadVendor();if(!dlg.open)return;const reader=V.createBarcodeReader();
  scanControls=await reader.decodeFromConstraints({video:{facingMode:{ideal:"environment"}}},$("#scanVideo"),(result)=>{if(result&&scanControls){const code=result.getText();stopScanner();handleBarcode(code)}});
  if(!dlg.open)stopScanner();else $("#scanStatus").textContent="Point the camera at the barcode."}
 catch(e){$("#scanStatus").textContent=/Permission|NotAllowed/i.test(e?.name+e?.message)?"Camera access was blocked. Allow it in Settings → Safari → Camera, or type the number below.":(e?.message||"Camera unavailable")+" You can type the number below."}}
async function handleBarcode(code){code=String(code).replace(/\D/g,"");if(code.length<8)return $("#scanStatus").textContent="That doesn’t look like a product barcode.";
 $("#scanStatus").textContent=`Looking up ${code}…`;
 try{const item=await lookupBarcode(code);if(!item){$("#scanStatus").textContent=`No product found for ${code} in Open Food Facts. Enter it by hand or search by name.`;return}
  stopScanner();$("#scanDialog").close();if(scanTarget){const t=scanTarget;scanTarget=null;t(item);return}showPage("food");foodSearch={query:"",results:null,loading:false,error:"",picked:null,open:true};pickFood(item)}
 catch{$("#scanStatus").textContent="Couldn’t look up that barcode. Check your connection."}}

// ---- Photo estimates via Claude (user's own Anthropic key)
async function imageToJpegBase64(file){const bitmap=await createImageBitmap(file),scale=Math.min(1,1024/Math.max(bitmap.width,bitmap.height)),c=document.createElement("canvas");c.width=Math.round(bitmap.width*scale);c.height=Math.round(bitmap.height*scale);c.getContext("2d").drawImage(bitmap,0,0,c.width,c.height);bitmap.close?.();return c.toDataURL("image/jpeg",.85).split(",")[1]}
let photoEstimate=null;
function drawPhotoResult(){const box=$("#photoResult"),e=photoEstimate;if(!e){box.innerHTML="";return}
 if(e.loading){box.innerHTML=`<p class="muted">Estimating… this can take 10–30 seconds.</p>`;return}
 if(e.error){box.innerHTML=`<p class="muted">${esc(e.error)}</p>`;return}
 if(!e.is_food||!e.items.length){box.innerHTML=`<p class="muted">No food recognized in that photo.</p>`;return}
 box.innerHTML=`${e.items.map((it,i)=>`<label class="pick-item"><input type="checkbox" data-photo-item="${i}" checked><span><b>${esc(it.name)}</b> · ${esc(it.portion)}<br><span class="small">${macroText({calories:it.calories,protein:it.protein_g,carbs:it.carbs_g,fat:it.fat_g})}</span></span></label>`).join("")}<p class="small">Confidence: ${esc(e.confidence)}. ${esc(e.notes)} Estimates can be off; adjust entries afterward if needed.</p><div class="photo-total"><span>Selected total</span><b id="photoTotal"></b></div><button class="btn full" id="addPhotoItems">Add selected</button>`;
 const sumSelected=()=>{const t={calories:0,protein:0,carbs:0,fat:0};let n=0;document.querySelectorAll("[data-photo-item]").forEach(cb=>{if(!cb.checked)return;const it=e.items[+cb.dataset.photoItem];t.calories+=+it.calories||0;t.protein+=+it.protein_g||0;t.carbs+=+it.carbs_g||0;t.fat+=+it.fat_g||0;n++});$("#photoTotal").textContent=n?macroText(t):"Nothing selected";$("#addPhotoItems").textContent=n?`Add ${n} item${n>1?"s":""}`:"Add selected"};
 document.querySelectorAll("[data-photo-item]").forEach(cb=>cb.onchange=sumSelected);sumSelected();
 $("#addPhotoItems").onclick=()=>{const date=foodDate||today(),meal=$("#photoMeal").value,now=new Date().toISOString();let n=0;
  document.querySelectorAll("[data-photo-item]").forEach(cb=>{if(!cb.checked)return;const it=e.items[+cb.dataset.photoItem];data.foods.push({id:uid(),date,meal,name:`${it.name} (${it.portion})`,calories:g0(it.calories),protein:r1(it.protein_g),carbs:r1(it.carbs_g),fat:r1(it.fat_g),source:"photo",createdAt:now});n++});
  if(!n)return alert("Select at least one item.");photoEstimate=null;$("#photoDialog").close();save()}}
async function runPhotoEstimate(file){photoEstimate={loading:true};drawPhotoResult();
 try{const [V,b64]=await Promise.all([loadVendor(),imageToJpegBase64(file)]);
  try{photoEstimate=await V.estimateFoodPhoto(getKeys().anthropic,b64,"image/jpeg",$("#photoNote").value.trim())}catch(err){photoEstimate={error:V.describeError(err)}}}
 catch(err){photoEstimate={error:err?.message||"Couldn’t read that photo."}}
 drawPhotoResult()}
// ---- Recipes and meals (Meals tab). Recipe ingredients and meal foods store their own nutrition; meal recipe items
// point at a recipe by id so edits to the recipe carry through.
const ZERO={calories:0,protein:0,carbs:0,fat:0};
const addN=(a,b,k=1)=>({calories:a.calories+(+b.calories||0)*k,protein:a.protein+(+b.protein||0)*k,carbs:a.carbs+(+b.carbs||0)*k,fat:a.fat+(+b.fat||0)*k});
const recipeById=id=>data.recipes.find(r=>r.id===id);
function recipeTotals(r){return r.ingredients.reduce((t,x)=>addN(t,x),ZERO)}
function recipePerServing(r){const t=recipeTotals(r),n=Math.max(+r.servings||1,0.01);return {calories:t.calories/n,protein:t.protein/n,carbs:t.carbs/n,fat:t.fat/n}}
const servingsText=n=>`${r1(n)} serving${r1(n)===1?"":"s"}`;
function mealItemFood(it){if(it.type!=="recipe")return it;const r=recipeById(it.recipeId);if(!r)return null;const ps=recipePerServing(r),k=+it.servings||0;return {name:`${r.name} (${servingsText(k)})`,calories:ps.calories*k,protein:ps.protein*k,carbs:ps.carbs*k,fat:ps.fat*k}}
function mealTotals(m){return m.items.map(mealItemFood).filter(Boolean).reduce((t,x)=>addN(t,x),ZERO)}
let mealsUI={recipe:null,meal:null,log:null};
function logFoods(items,date,meal,source){const now=new Date().toISOString();for(const f of items)data.foods.push({id:uid(),date,meal,name:f.name,calories:g0(f.calories),protein:r1(f.protein),carbs:r1(f.carbs),fat:r1(f.fat),source,createdAt:now})}
function logFormMarkup(kind,id){const isRecipe=kind==="recipe";return `<div class="lookup log-form"><div class="row"><div class="field" style="margin:0"><label>Day</label><input type="date" id="logDate" value="${foodDate||today()}"></div><div class="field" style="margin:0"><label>Meal</label><select id="logMeal">${MEALS.map(m=>`<option ${m===defaultMeal()?"selected":""}>${m}</option>`).join("")}</select></div>${isRecipe?`<div class="field" style="margin:0;flex:.7"><label>Servings</label><input type="number" id="logServings" min="0" step="any" inputmode="decimal" value="1"></div>`:""}</div><div class="small" id="logPreview" style="margin-top:8px"></div><div class="row" style="margin-top:10px"><button class="btn secondary" id="logCancel">Cancel</button><button class="btn" id="logConfirm">Add to food log</button></div></div>`}
function drawMeals(){const page=$("#page-meals");if(!page)return;const ui=mealsUI;
 const rowButtons=(kind,id)=>`<div class="mini-actions"><button class="btn sm" data-log="${kind}:${esc(id)}">Log</button><button class="btn secondary sm" data-edit="${kind}:${esc(id)}">${ui[kind]===id?"Done":"Edit"}</button><button class="icon-btn danger" data-del="${kind}:${esc(id)}" aria-label="Delete">✕</button></div>`;
 const ingredientRow=(f,i,kind,extra="")=>`<div class="ing-row"><div><div class="entry-title">${esc(f.name)}</div><div class="entry-detail">${macroText(f)}</div>${extra}</div><button class="icon-btn danger" data-del-item="${kind}:${i}" aria-label="Remove">✕</button></div>`;
 page.innerHTML=`<div class="card"><h2>Meals</h2><p class="small" style="margin-top:-4px">Combine foods and recipes you often eat together, then log them in one tap.</p>${data.meals.length?"":`<p class="muted">No meals yet.</p>`}${data.meals.map(m=>{const t=mealTotals(m),editing=ui.meal===m.id;return `<div class="meal-item"><div class="meal-head"><div><div class="entry-title">${esc(m.name)}</div><div class="entry-detail">${m.items.length} item${m.items.length===1?"":"s"} · ${macroText(t)}</div></div></div>${rowButtons("meal",m.id)}${ui.log?.kind==="meal"&&ui.log.id===m.id?logFormMarkup("meal",m.id):""}${editing?`<div class="editor"><div class="field"><label>Meal name</label><input data-name="meal" value="${esc(m.name)}"></div>${m.items.map((it,i)=>{const f=mealItemFood(it);if(!f)return "";return ingredientRow(f,i,"meal",it.type==="recipe"?`<label class="small inline-num">Servings <input type="number" min="0" step="any" inputmode="decimal" data-item-servings="${i}" value="${r1(it.servings)}"></label>`:"")}).join("")}<button class="btn secondary full" data-add-item="meal">Add food or recipe</button></div>`:""}</div>`}).join("")}<button class="btn full" id="newMeal" style="margin-top:12px">New meal</button></div>
 <div class="card"><h2>Recipes</h2><p class="small" style="margin-top:-4px">Add ingredients and how many servings the recipe makes; nutrition is worked out per serving.</p>${data.recipes.length?"":`<p class="muted">No recipes yet.</p>`}${data.recipes.map(r=>{const ps=recipePerServing(r),t=recipeTotals(r),editing=ui.recipe===r.id;return `<div class="meal-item"><div class="meal-head"><div><div class="entry-title">${esc(r.name)}</div><div class="entry-detail">Per serving: ${macroText(ps)}<br>Makes ${servingsText(+r.servings||1)} · ${r.ingredients.length} ingredient${r.ingredients.length===1?"":"s"}</div></div></div>${rowButtons("recipe",r.id)}${ui.log?.kind==="recipe"&&ui.log.id===r.id?logFormMarkup("recipe",r.id):""}${editing?`<div class="editor"><div class="row"><div class="field" style="flex:2"><label>Recipe name</label><input data-name="recipe" value="${esc(r.name)}"></div><div class="field"><label>Servings</label><input type="number" min="0" step="any" inputmode="decimal" id="recipeServings" value="${r1(r.servings||1)}"></div></div>${r.ingredients.map((f,i)=>ingredientRow(f,i,"recipe")).join("")}${r.ingredients.length?`<div class="photo-total"><span>Whole recipe</span><b>${macroText(t)}</b></div>`:""}<button class="btn secondary full" data-add-item="recipe">Add ingredient</button></div>`:""}</div>`}).join("")}<button class="btn full" id="newRecipe" style="margin-top:12px">New recipe</button></div>`;
 // create
 page.querySelector("#newMeal").onclick=()=>{const name=prompt("Name for the meal","Breakfast");if(!name?.trim())return;const m={id:uid(),name:name.trim(),items:[]};data.meals.push(m);mealsUI={recipe:null,meal:m.id,log:null};save();openPicker({allowRecipes:true,title:"Add to "+m.name,onPick:it=>{m.items.push(it);save()}})};
 page.querySelector("#newRecipe").onclick=()=>{const name=prompt("Name for the recipe","");if(!name?.trim())return;const r={id:uid(),name:name.trim(),servings:1,ingredients:[]};data.recipes.push(r);mealsUI={recipe:r.id,meal:null,log:null};save()};
 page.querySelectorAll("[data-edit]").forEach(b=>b.onclick=()=>{const [kind,id]=b.dataset.edit.split(":");const open=mealsUI[kind]===id;mealsUI={recipe:null,meal:null,log:null};if(!open)mealsUI[kind]=id;drawMeals()});
 page.querySelectorAll("[data-del]").forEach(b=>b.onclick=()=>{const [kind,id]=b.dataset.del.split(":");
  if(kind==="meal"){const m=data.meals.find(x=>x.id===id);if(!confirm(`Delete the ${m.name} meal? Foods already logged stay in your log.`))return;data.meals=data.meals.filter(x=>x.id!==id)}
  else{const r=recipeById(id),used=data.meals.filter(m=>m.items.some(it=>it.recipeId===id)).map(m=>m.name);if(!confirm(`Delete the ${r.name} recipe?${used.length?` It will also be removed from ${used.join(", ")}.`:""} Foods already logged stay in your log.`))return;data.recipes=data.recipes.filter(x=>x.id!==id);for(const m of data.meals)m.items=m.items.filter(it=>it.recipeId!==id)}
  if(mealsUI[kind]===id)mealsUI[kind]=null;if(mealsUI.log?.id===id)mealsUI.log=null;save()});
 // log
 page.querySelectorAll("[data-log]").forEach(b=>b.onclick=()=>{const [kind,id]=b.dataset.log.split(":");const same=mealsUI.log?.id===id;mealsUI.log=same?null:{kind,id};drawMeals()});
 if(ui.log){const {kind,id}=ui.log,item=kind==="meal"?data.meals.find(x=>x.id===id):recipeById(id);
  const foods=()=>kind==="meal"?item.items.map(mealItemFood).filter(Boolean):(()=>{const s=+page.querySelector("#logServings").value||0,ps=recipePerServing(item);return s>0?[{name:`${item.name} (${servingsText(s)})`,calories:ps.calories*s,protein:ps.protein*s,carbs:ps.carbs*s,fat:ps.fat*s}]:[]})();
  const preview=()=>{const f=foods();page.querySelector("#logPreview").textContent=f.length?`${f.length>1?`${f.length} entries · `:""}${macroText(f.reduce((t,x)=>addN(t,x),ZERO))}`:"Nothing to log yet."};
  page.querySelector("#logServings")?.addEventListener("input",preview);preview();
  page.querySelector("#logCancel").onclick=()=>{mealsUI.log=null;drawMeals()};
  page.querySelector("#logConfirm").onclick=()=>{const f=foods();if(!f.length)return alert(kind==="meal"?"Add foods to this meal first.":"Enter the number of servings, and add ingredients to the recipe first.");
   const date=page.querySelector("#logDate").value||today(),meal=page.querySelector("#logMeal").value;logFoods(f,date,meal,kind);mealsUI.log=null;save();alert(`Added to ${meal}, ${date===today()?"today":dateText(date)}.`)}}
 // editors
 const editing=ui.meal?["meal",data.meals.find(x=>x.id===ui.meal)]:ui.recipe?["recipe",recipeById(ui.recipe)]:null;
 if(!editing||!editing[1])return;const [kind,obj]=editing,list=kind==="meal"?obj.items:obj.ingredients;
 const nameInput=page.querySelector(`[data-name="${kind}"]`);nameInput.oninput=()=>{obj.name=nameInput.value;persist()};nameInput.onchange=()=>{obj.name=nameInput.value.trim()||"Untitled";save()};
 page.querySelector("#recipeServings")?.addEventListener("change",e=>{obj.servings=Math.max(+e.target.value||1,0.01);save()});
 page.querySelectorAll("[data-item-servings]").forEach(inp=>inp.onchange=()=>{obj.items[+inp.dataset.itemServings].servings=Math.max(+inp.value||0,0);save()});
 page.querySelectorAll("[data-del-item]").forEach(b=>b.onclick=()=>{list.splice(+b.dataset.delItem.split(":")[1],1);save()});
 page.querySelector("[data-add-item]").onclick=()=>openPicker({allowRecipes:kind==="meal",title:kind==="meal"?`Add to ${obj.name}`:`Add ingredient to ${obj.name}`,onPick:it=>{if(kind==="recipe"&&it.type==="recipe")return;list.push(it);save()}})}

// ---- Food picker dialog shared by recipes and meals: search, barcode, recent foods, recipes, or manual entry.
let pickState=null,scanTarget=null;
function openPicker(opts){pickState={...opts,query:"",results:null,loading:false,error:"",picked:null,recipe:null};$("#pickTitle").textContent=opts.title||"Add food";drawPicker();$("#pickDialog").showModal()}
function finishPick(item){const s=pickState;$("#pickDialog").close();pickState=null;s.onPick(item)}
function drawPicker(){const s=pickState,body=$("#pickBody");if(!s)return;
 if(s.picked){const p=s.picked,n=pickedNutrition(p);body.innerHTML=`<div class="entry-title">${esc(p.name)}</div><div class="small">${esc(p.source)} · per 100 g: ${g0(p.per100.calories)} kcal</div><div class="row" style="margin-top:8px"><div class="field" style="margin:0"><label>Amount</label><input id="pkAmount" type="number" min="0" step="any" inputmode="decimal" value="${esc(p.amount)}"></div><div class="field" style="margin:0;flex:1.6"><label>Unit</label><select id="pkUnit">${p.portions.map((x,i)=>`<option value="p${i}" ${p.unit==="p"+i?"selected":""}>${esc(x.label)} · ${r1(x.grams)} g</option>`).join("")}<option value="g" ${p.unit==="g"?"selected":""}>grams</option><option value="oz" ${p.unit==="oz"?"selected":""}>ounces</option></select></div></div><div class="small" id="pkTotals" style="margin-top:8px">${macroText(n)}</div><div class="row" style="margin-top:10px"><button class="btn secondary" id="pkBack">Back</button><button class="btn" id="pkUse">Add</button></div>`;
  const upd=()=>{p.amount=+body.querySelector("#pkAmount").value||0;p.unit=body.querySelector("#pkUnit").value;body.querySelector("#pkTotals").textContent=macroText(pickedNutrition(p))};body.querySelector("#pkAmount").oninput=upd;body.querySelector("#pkUnit").onchange=upd;
  body.querySelector("#pkBack").onclick=()=>{s.picked=null;drawPicker()};
  body.querySelector("#pkUse").onclick=()=>{upd();if(!(pickedGrams(p)>0))return alert("Enter an amount.");finishPick({type:"food",name:`${p.name} (${pickedLabel(p)})`,...pickedNutrition(p)})};return}
 if(s.recipe){const r=s.recipe;body.innerHTML=`<div class="entry-title">${esc(r.name)}</div><div class="small">Per serving: ${macroText(recipePerServing(r))}</div><div class="field"><label>Servings</label><input id="pkServ" type="number" min="0" step="any" inputmode="decimal" value="1"></div><div class="row"><button class="btn secondary" id="pkBack">Back</button><button class="btn" id="pkUse">Add</button></div>`;
  body.querySelector("#pkBack").onclick=()=>{s.recipe=null;drawPicker()};body.querySelector("#pkUse").onclick=()=>{const n=+body.querySelector("#pkServ").value||0;if(!(n>0))return alert("Enter the number of servings.");finishPick({type:"recipe",recipeId:r.id,servings:n})};return}
 const recent=recentFoods();
 body.innerHTML=`<div class="row"><input id="pkQuery" class="search-input" placeholder="Search foods, e.g. chicken breast" value="${esc(s.query)}" enterkeyhint="search"><button class="btn" id="pkGo" style="flex:0 0 auto">Go</button></div><button class="btn secondary full" id="pkScan" style="margin-top:8px">Scan barcode</button>
  ${s.loading?`<p class="muted">Searching…</p>`:s.results?`<div class="lookup">${s.error?`<p class="muted" style="margin:0">${esc(s.error)}</p>`:s.results.map((r,i)=>`<button class="result" data-pk-result="${i}"><b>${esc(r.name)}</b><span>${g0(r.per100.calories)} kcal / 100 g · ${esc(r.source)}</span></button>`).join("")}</div>`:""}
  ${s.allowRecipes&&data.recipes.length?`<h3 style="margin-top:14px">Your recipes</h3><div class="chips">${data.recipes.map((r,i)=>`<button class="chip" data-pk-recipe="${i}">${esc(r.name)} <span>${g0(recipePerServing(r).calories)}/serving</span></button>`).join("")}</div>`:""}
  ${recent.length?`<h3 style="margin-top:14px">Recent foods</h3><div class="chips">${recent.map((f,i)=>`<button class="chip" data-pk-recent="${i}">${esc(f.name)} <span>${esc(f.calories)}</span></button>`).join("")}</div>`:""}
  <h3 style="margin-top:14px">Enter manually</h3><div class="field" style="margin-top:6px"><input id="pkName" class="search-input" placeholder="Food name"></div><div class="exercise-grid" style="grid-template-columns:repeat(4,1fr)">${[["Kcal","calories"],["Prot g","protein"],["Carb g","carbs"],["Fat g","fat"]].map(([l,k])=>`<label class="small">${l}<input type="number" min="0" step="any" inputmode="decimal" id="pk-${k}"></label>`).join("")}</div><button class="btn secondary full" id="pkManual" style="margin-top:10px">Add</button>`;
 const go=async()=>{const q=body.querySelector("#pkQuery").value.trim();if(!q)return;s.query=q;s.loading=true;s.results=null;drawPicker();
  const [u,o]=await Promise.allSettled([searchUSDA(q),searchOFF(q)]);if(pickState!==s||s.query!==q)return;const results=[...(u.status==="fulfilled"?u.value:[]),...(o.status==="fulfilled"?o.value:[])],errs=[u,o].filter(r=>r.status==="rejected").map(r=>r.reason?.message);
  s.loading=false;s.results=results;s.error=results.length?"":errs.length?errs.join(" "):"No matches. Try a simpler name.";drawPicker()};
 body.querySelector("#pkGo").onclick=go;body.querySelector("#pkQuery").onkeydown=e=>{if(e.key==="Enter"){e.preventDefault();go()}};
 body.querySelectorAll("[data-pk-result]").forEach(b=>b.onclick=()=>{const it=s.results[+b.dataset.pkResult];s.picked={...it,amount:it.portions.length?1:100,unit:it.portions.length?"p0":"g"};drawPicker()});
 body.querySelectorAll("[data-pk-recipe]").forEach(b=>b.onclick=()=>{s.recipe=data.recipes[+b.dataset.pkRecipe];drawPicker()});
 body.querySelectorAll("[data-pk-recent]").forEach(b=>b.onclick=()=>{const f=recent[+b.dataset.pkRecent];finishPick({type:"food",name:f.name,calories:+f.calories||0,protein:+f.protein||0,carbs:+f.carbs||0,fat:+f.fat||0})});
 body.querySelector("#pkScan").onclick=()=>{scanTarget=item=>{if(pickState!==s)return;s.picked={...item,amount:item.portions.length?1:100,unit:item.portions.length?"p0":"g"};drawPicker()};openScanner()};
 body.querySelector("#pkManual").onclick=()=>{const name=body.querySelector("#pkName").value.trim(),cal=body.querySelector("#pk-calories").value;if(!name)return alert("Enter the food name.");if(cal===""||!(+cal>=0))return alert("Enter the calories.");
  finishPick({type:"food",name,calories:g0(cal),protein:r1(body.querySelector("#pk-protein").value),carbs:r1(body.querySelector("#pk-carbs").value),fat:r1(body.querySelector("#pk-fat").value)})}}
function render(){home();drawMeals();drawPlan();drawFood();drawLift();drawRides();drawProgress();drawHistory();$("#todayLabel").textContent=new Date().toLocaleDateString(undefined,{weekday:"long",month:"long",day:"numeric"})}
window.showPage=name=>{document.querySelectorAll(".tab").forEach(b=>b.classList.toggle("active",b.dataset.page===name));document.querySelectorAll(".page").forEach(p=>p.classList.toggle("active",p.id===`page-${name}`));if(name==="lift")drawLift();if(name==="food")drawFood();if(name==="plan")drawPlan();if(name==="meals")drawMeals()};document.querySelectorAll(".tab").forEach(b=>b.onclick=()=>showPage(b.dataset.page));
// Photos use IndexedDB so image files do not consume the small localStorage quota used by workout records.
let photoDBPromise=null,photoURLs=[];
function photoDB(){return photoDBPromise||(photoDBPromise=new Promise((resolve,reject)=>{const req=indexedDB.open("best-exercise-photos",1);req.onupgradeneeded=()=>req.result.createObjectStore("photos");req.onsuccess=()=>{const db=req.result;db.onclose=()=>{photoDBPromise=null};resolve(db)};req.onerror=()=>{photoDBPromise=null;reject(req.error)}}))}
// Removes stored photos whose ids are not in keep (used after a restore so replaced photos don't linger).
async function photoPrune(keep){const db=await photoDB();return new Promise(resolve=>{const tx=db.transaction("photos","readwrite"),store=tx.objectStore("photos"),req=store.getAllKeys();req.onsuccess=()=>{for(const k of req.result)if(!keep.has(k))store.delete(k)};tx.oncomplete=resolve;tx.onerror=resolve})}
async function photoPut(id,blob){const db=await photoDB();return new Promise((resolve,reject)=>{const tx=db.transaction("photos","readwrite");tx.objectStore("photos").put(blob,id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
async function photoGet(id){const db=await photoDB();return new Promise((resolve,reject)=>{const req=db.transaction("photos").objectStore("photos").get(id);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function photoDelete(id){const db=await photoDB();return new Promise(resolve=>{const tx=db.transaction("photos","readwrite");tx.objectStore("photos").delete(id);tx.oncomplete=resolve;tx.onerror=resolve})}
async function compressImage(file){const bitmap=await createImageBitmap(file),scale=Math.min(1,1200/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement("canvas");canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext("2d").drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();return new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(new Error("Image conversion failed")),"image/jpeg",.78))}
async function renderPhotoGrid(el){if(!el)return;el.innerHTML="";for(const u of photoURLs)URL.revokeObjectURL(u);photoURLs=[];for(const p of data.photos.slice().sort((a,b)=>b.date.localeCompare(a.date))){const card=document.createElement("div");card.className="entry";try{const blob=await photoGet(p.id);if(blob){const img=document.createElement("img");img.className="photo";img.src=URL.createObjectURL(blob);photoURLs.push(img.src);img.alt=p.label;card.append(img)}}catch{}const title=document.createElement("div");title.className="entry-title";title.textContent=`${p.label} · ${dateText(p.date)}`;card.append(title);const del=document.createElement("button");del.className="btn danger";del.style.cssText="margin-top:7px;padding:7px 10px";del.textContent="Delete";del.onclick=async()=>{await photoDelete(p.id);data.photos=data.photos.filter(x=>x.id!==p.id);save()};card.append(del);el.append(card)}}
function blobToData(blob){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(blob)})}function dataToBlob(url){const [meta,b64]=url.split(","),mime=meta.match(/:(.*?);/)[1],bin=atob(b64),arr=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)arr[i]=bin.charCodeAt(i);return new Blob([arr],{type:mime})}
async function backup(){const photos=[];for(const p of data.photos){const blob=await photoGet(p.id);if(blob)photos.push({...p,image:await blobToData(blob)})}const out={format:"B.E.S.T. exercise tracker backup",version:1,data:{...data,photos:[]},photos},name=`best-backup-${today()}.json`,blob=new Blob([JSON.stringify(out)],{type:"application/json"});
 // On a phone, the share sheet ("Save to Files") is more reliable than a download link, especially from the Home Screen app.
 if(matchMedia("(pointer:coarse)").matches)try{const file=new File([blob],name,{type:"application/json"});if(navigator.canShare?.({files:[file]})){await navigator.share({files:[file],title:"B.E.S.T. backup"});return}}catch(e){if(e?.name==="AbortError")return}
 const a=document.createElement("a"),url=URL.createObjectURL(blob);a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000)}
const backupDialog=$("#backupDialog");
$("#backupBtn").onclick=()=>backupDialog.showModal();$("#closeBackup").onclick=()=>backupDialog.close();
$("#exportBackup").onclick=()=>{backupDialog.close();backup().catch(()=>alert("The backup could not be created."))};
$("#restoreBackup").onclick=()=>{backupDialog.close();$("#restoreFile").click()};
$("#restoreFile").onchange=async ev=>{const f=ev.target.files[0];if(!f)return;try{const o=JSON.parse(await f.text());if(!o.data||!Array.isArray(o.photos))throw new Error("Invalid backup");if(!confirm("Restoring replaces all workouts, routines, food, meals, recipes, rides, measurements, and photos on this device with the backup. Continue?"))return;for(const p of o.photos)await photoPut(p.id,dataToBlob(p.image));const next={...structuredClone(defaults),...o.data,photos:o.photos.map(({image,...p})=>p)};for(const k of ["workouts","rides","measurements","foods"])if(!Array.isArray(next[k]))next[k]=[];if(!next.foodGoals||typeof next.foodGoals!=="object")next.foodGoals={calories:0,protein:0,carbs:0,fat:0};normalizeData(next);data=next;currentExercises=[];currentSplit=null;save();await photoPrune(new Set(data.photos.map(p=>p.id)));alert("Backup restored.")}catch{alert("That backup file could not be restored.")}finally{ev.target.value=""}};
